import { readFileSync } from 'node:fs';
import { sign } from 'node:crypto';
import { createPrivateKey } from 'node:crypto';
import { describe, expect, it } from 'vitest';
import { verifyP256 } from '../src/auth/crypto.js';

// Cross-language wire parity: the Flutter app's device key (apps/surau-app) must sign the unlock
// message so the box accepts it, and the box's Node vectors must stay the ones Dart verifies.
// Fixtures: node-signed.json is generated by `node scripts/gen-app-fixtures.mjs --vectors`;
// dart-signed.json is written by apps/surau-app/test/box/device_key_test.dart.
const dir = new URL('../../surau-app/test/fixtures/vectors/', import.meta.url);
const read = (name: string) => JSON.parse(readFileSync(new URL(name, dir), 'utf8'));

describe('Dart client signatures verify in the box', () => {
  const dart = read('dart-signed.json') as {
    publicJwk: Record<string, string>;
    messageHex: string;
    signatureB64url: string;
  };
  const node = read('node-signed.json') as {
    boxId: string;
    deviceId: string;
    nonce: string;
    messageHex: string;
    publicJwk: Record<string, string>;
    privateJwk: Record<string, string>;
    signatureB64url: string;
  };

  it('dart-signed.json is accepted by verifyP256', () => {
    const message = Buffer.from(dart.messageHex, 'hex');
    const sig = Buffer.from(dart.signatureB64url, 'base64url');
    expect(sig.length).toBe(64);
    expect(dart.signatureB64url).not.toMatch(/[=+/]/);
    expect(Object.keys(dart.publicJwk).sort()).toEqual(['crv', 'kty', 'x', 'y']);
    expect(verifyP256(dart.publicJwk, message, sig)).toBe(true);
  });

  it('a flipped byte, a wrong message or a DER-length signature is refused', () => {
    const message = Buffer.from(dart.messageHex, 'hex');
    const sig = Buffer.from(dart.signatureB64url, 'base64url');
    for (const i of [0, 31, 32, 63]) {
      const bad = Buffer.from(sig);
      bad[i]! ^= 1;
      expect(verifyP256(dart.publicJwk, message, bad)).toBe(false);
    }
    expect(verifyP256(dart.publicJwk, Buffer.from('other'), sig)).toBe(false);
    expect(verifyP256(dart.publicJwk, message, sig.subarray(0, 63))).toBe(false);
  });

  it('the message both sides sign is the box message layout', () => {
    const expected = `surau-unlock\n${node.boxId}\n${node.deviceId}\n${node.nonce}`;
    expect(Buffer.from(node.messageHex, 'hex').toString('utf8')).toBe(expected);
    expect(dart.messageHex).toBe(node.messageHex);
  });

  it('the Node vector verifies in the box and the Dart public key equals the Node one', () => {
    const message = Buffer.from(node.messageHex, 'hex');
    expect(verifyP256(node.publicJwk, message, Buffer.from(node.signatureB64url, 'base64url'))).toBe(true);
    expect(dart.publicJwk).toEqual(node.publicJwk);
  });

  it('the Node private key still produces the committed vector shape (P1363, 64 bytes)', () => {
    const key = createPrivateKey({ key: node.privateJwk, format: 'jwk' });
    const sig = sign('sha256', Buffer.from(node.messageHex, 'hex'), { key, dsaEncoding: 'ieee-p1363' });
    expect(sig.length).toBe(64);
  });
});
